export const DECKS = [{"id":"d1","n":"终天教团 · 熵火","en":"ENTROPY PYRE","r":"chaos","desc":"用命换速度。召唤即伤害，伤害即抽牌；血条是自己点的火，烧到对面先熄。","cards":[["m01",2],["m02",3],["m03",2],["m07",1],["m09",1],["m11",1],["m12",2],["m13",1],["m14",2],["s02",1],["s06",1],["s10",1],["s12",1],["s01",1],["t02",2],["t06",1],["t03",1],["t19",1],["s03",1],["s07",2],["t09",1],["s11",1]],"extra":["e04","e09"],"combo":["「24」或「潘狄娅」先落地，一张牌换一次抽牌或 500 点直伤。","「猩红邀约」贴在「凯蒂古拉」上，2100 变 3100，贯穿直接打穿守备。","「熔毁·朵尔」＋「24」＝「熵王·熔毁之冠」：3300 贯穿，登场再拆一只。"],"tips":"不要省血。这套牌的生命值是资源，6000 里有 2000 是拿来烧的；但要留在 1500 以上，否则一张「融蚀风暴」就结束了。"},{"id":"d2","n":"弥萨格夜巡","en":"NIGHT WATCH","r":"ultra","desc":"不抢血，抢节奏。用反击陷阱把对方的每一步都变成一次无效，最后让波吕克斯收场。","cards":[["m51",2],["m49",3],["m43",2],["m44",1],["m46",1],["m47",1],["m48",1],["m50",2],["m53",1],["s26",2],["s24",2],["s21",1],["s23",1],["s03",1],["t06",2],["t07",1],["t03",1],["t14",1],["t16",1],["m54",1],["s08",2]],"extra":["e02","e05"],"combo":["「卡茜亚」「珈伦」这类检索卡先找齐反击：「悖论」管魔法，「圣所钟声」管召唤。","「界外之音」在场后每回合多抽 1，反击牌永远比对手多一张。","「波吕克斯」＋「詹金」＝「夜巡·弥萨格之眼」，3200 贯穿，还能封一张陷阱。"],"tips":"盖牌顺序有讲究：先盖「圣所钟声」再盖「悖论」，对手往往会先试魔法、被你换掉一张。"},{"id":"d3","n":"深潜回响","en":"DEEP ECHO","r":"aqua","desc":"把对手的场面一张张弹回手牌，用抽牌把资源差距拉到对手看不懂的地方。","cards":[["m29",2],["m30",1],["m32",2],["m33",2],["m35",2],["m37",1],["m39",1],["m40",3],["s17",2],["s18",2],["s19",1],["s20",1],["s01",1],["s02",1],["s08",1],["t13",3],["t02",1],["t04",1],["t12",1],["m34",1]],"extra":["e03"],"combo":["「奥瑞塔」落地抽 1，「海祭典仪」在两只深海站住后再开，一次两张。","「潮汐逆转」＋「深渊之口」＝ 两次弹回，对方的祭品永远凑不齐。","「墨菲」＋「法洛思」＝「深潜·诞妄回响」，3000 守备 2600，登场抽 2。"],"tips":"这套牌不怕拖。牌差一旦到 3 张以上，就用「沉于深渊」让对手每次召唤都要丢牌。"},{"id":"d4","n":"血肉之诺","en":"COVENANT OF FLESH","r":"caro","desc":"不追求一波打死。每回合回一点、每只怪兽多站一会儿，等「血链·希洛」把差距连本带利收回来。","cards":[["m15",1],["m16",2],["m17",1],["m18",1],["m19",1],["m20",3],["m21",2],["m24",2],["m25",2],["m28",1],["s13",1],["s14",2],["s15",1],["s16",1],["s07",1],["s05",1],["s01",1],["t12",1],["t01",1],["t18",1],["s06",1],["t02",2]],"extra":["e08","e10"],"combo":["「菲茵特」＋「无尽星光」：每个回合结束回 800，两回合就把一张「融蚀风暴」赚回来。","「索蕾尔」付 500 换 500 攻，配「再生之躯」变成 2500 攻 / 2900 守的双面怪。","「杜勒赛因」＋「索蕾尔」＝「血月·杜勒赛因」：3300，打一下回一次。"],"tips":"血量领先时不要急着进攻。这套牌的胜点常在对手牌库见底那两回合。"},{"id":"d5","n":"虚无教义","en":"DOCTRINE OF NOTHING","r":"any","desc":"终天教团的另一种传教方式：不主动进攻，只让对手每一次出手都付出代价。十张陷阱，四界齐备。","cards":[["m04",2],["m05",2],["m16",1],["m39",2],["m43",2],["m47",2],["m48",1],["m53",2],["s01",1],["s02",1],["s08",3],["s06",1],["t01",2],["t02",1],["t03",2],["t06",1],["t07",1],["t19",1],["t20",1],["t11",1]],"extra":["e12"],"combo":["「诺缔拉」「莉莉」「旺达」三个守备怪站满，对手只能先拆墙。","「弥萨格的黄昏」＋「终天之诗」：每回合净赚 300 血差，十回合就是 3000。","四界齐备触发「四界混编」，一堵 1200 攻的墙也能咬人。"],"tips":"盖牌不要一次盖满。留一格空位，对手会误判你没有第二张「融蚀之槛」。"},{"id":"d6","n":"校猫的私藏","en":"THE CAT'S DRAWER","r":"any","desc":"四界混编的杂牌，靠觉醒体翻盘。没人知道下一张是什么——包括你自己。","cards":[["m09",2],["m12",1],["m18",2],["m40",1],["m42",1],["m48",2],["m51",1],["m52",1],["m55",1],["m56",1],["s01",1],["s06",2],["t01",1],["t11",1],["t14",1],["t16",2],["s14",1],["s09",1],["t12",2],["m38",1],["s02",1],["m54",1],["s23",1],["s18",1]],"extra":["e12","e07","e06"],"combo":["「校猫的恶作剧」拆掉对手唯一一张盖牌，然后「弥萨格校猫」登场：抽 1、对手弃 1。","「神王·图鲁」＋「威廉」＝「王权·终焉图鲁」，3800 攻还带守备嘲讽。","「N」＋「汀克特」＝「悖论·无解之环」，一次弃牌、一次抽牌、一次封陷阱。"],"tips":"这套牌什么都有，什么都不精。觉醒体是唯一的赢法：留好素材，别把它们当祭品吃掉。"},{"id":"d7","n":"超维观测所","en":"OBSERVATORY","r":"ultra","desc":"把「已经发生的事」改写成参数：检索、改写、无效，最后用一支净世投枪一次清算。","cards":[["m43",3],["m44",1],["m46",3],["m47",2],["m49",2],["m50",2],["m51",3],["m52",1],["m54",1],["s26",2],["s21",1],["s01",1],["s06",1],["t11",1],["m45",1],["s23",1],["t03",1],["t06",1],["m56",1],["m53",1]],"extra":["e05","e02"],"combo":["「观测者之眼」先从卡组把「达芙黛尔」或「莉兹」拿到手，凑齐净世投枪的两只素材。","「猫与灯」开局就给一张陷阱；「观测者的证词」让超维守备怪 +500，撑到觉醒那一步。","「净世之路」扫掉对方 1500 以下的杂兵，再让 3200 的「夜巡·弥萨格之眼」落地。"],"tips":"前期不该硬拼。反击陷阱留着等对手的关键魔法，别为了省 1000 点血把「悖论」用在便宜牌上。"},{"id":"d8","n":"圣所 · 负誓之壁","en":"SANCTUARY VOW","r":"caro","desc":"先靠守备与回复把场面拖住：等「血链·希洛」和「凯蒂古拉」同时到手，一张「终末·噬血链球」把前面攒的血一次收回来。","cards":[["m02",2],["m15",3],["m18",2],["m20",2],["m21",2],["m22",2],["m24",1],["m28",2],["m25",1],["s01",1],["s05",2],["s10",1],["s14",1],["s16",1],["t01",1],["t20",1],["t12",1],["m26",1],["t08",1],["s03",1],["t07",1]],"extra":["e01","e10"],"combo":["「圣所·负誓之壁」在场时对面只能打它：2700 / 3400 再贴「再生之躯」，几乎推不动。","「誓约之血」让每次回血多 300——一张「血之誓约」就变成 1300。","「血链·希洛」＋「凯蒂古拉」＝「终末·噬血链球」：3500 攻，登场再烧 1000。"],"tips":"素材可以一只手在场上、另一只从手牌来，所以别急着把「凯蒂古拉」当祭品用掉。血之偿还在墓地堆起来之后再用，900 点回血抵得上一张牌。"},{"id":"d9","n":"燃尽序曲","en":"PYRE OVERTURE","r":"chaos","desc":"全是小怪，全靠数量和直伤。三回合内没把对面压到 3000 以下，这套牌就没牌了。","cards":[["m01",2],["m02",1],["m03",2],["m06",2],["m07",2],["m08",1],["m09",2],["m11",2],["m13",3],["m14",2],["s01",1],["s05",1],["s06",1],["s09",2],["s11",2],["s12",2],["s04",1],["s02",1]],"extra":["e09","e11"],"combo":["「疯狂低语」给全场 +500：三只小怪站住时，一张牌就是 1500 的攻势。","「业火重燃」按墓地里混沌怪兽的数量烧脸，所以祭品在这里不是亏，是上膛。","「灰烬·萝坦双刃」一个战斗阶段打两次；「环行·无限回廊」登场还能从墓地捞回一张牌。"],"tips":"血也敢烧：「熵增逆转」用 1000 点血换 2 张牌，通常比多站一只 1300 的怪划算。"}];
export const LORE = {"_note":"《忘却前夜·唤醒王：决斗链接》的世界观与设定。术语沿用原作，卡牌规则与「唤醒王：决斗链接」这套玩法是本作私设。","intro":"这不是一场战争。战争会留下废墟，而这里连废墟都不会留下——被忘掉的东西不会变成灰，它只是从来没有存在过。","realms":[{"id":"chaos","n":"混沌","en":"CHAOS","color":"#e8656f","motto":"用身体换一个答案","desc":"熵的界域。这里的记忆是烧起来的：越是想记住什么，越要先把自己点着。混沌的唤醒体多半不在意代价，她们只在意那把火烧到谁身上。","style":"直伤 · 自损换攻 · 破坏"},{"id":"caro","n":"血肉","en":"CARO","color":"#d98b6a","motto":"伤口是可以谈条件的","desc":"血肉的界域。这里的规则很朴素：欠了就还。血可以当钱、当誓、当契约的墨水。血肉的唤醒体擅长把已经付出的东西再要回来一次。","style":"回复 · 墓地回收 · 耐战"},{"id":"aqua","n":"深海","en":"AEQUOR","color":"#5b9bd5","motto":"往下走，别回头","desc":"深海的界域。水会冲掉名字，也会把冲掉的东西堆在更深的地方。深海的唤醒体不急着杀你，她们只是让你的牌一张张离开该在的位置。","style":"抽牌 · 弹手 · 资源压制"},{"id":"ultra","n":"超维","en":"ULTRA","color":"#e3b341","motto":"已经发生的事，可以重写","desc":"维度的界域。这里的人看弥萨格像看一行注脚：既然只是注脚，就可以改。超维的唤醒体最擅长的不是进攻，是让对方的进攻「没有发生过」。","style":"无效 · 反击 · 检索"}],"chapters":[{"id":"c1","t":"一 · 忘却前夜","sub":"THE NIGHT BEFORE FORGETTING","quote":"那一夜没有火光，也没有喊声。第二天早上，少了一条街。","ps":["人们后来把那一夜叫做「忘却前夜」：不是遗忘的开始，而是遗忘被人们发现的那一晚。在那之前，融蚀已经吃了很多东西，只是没有人察觉——因为被吃掉的东西，连「少了什么」这个念头都一起没了。","融蚀不摧毁，它撤回。一栋楼不是倒塌，是从来没有人盖过；一个人不是死去，是户口本上从来没有这一行。世界上只剩下最后一座还在「记得」的城市：弥萨格。","弥萨格之所以还在，是因为城里有一群人自愿承担了全部的记忆。他们记得每一条被撤掉的街、每一个被撤掉的名字，代价是这些记忆会像石头一样压在他们身上，一天比一天重。"]},{"id":"c2","t":"二 · 守密人","sub":"THE KEEPER","quote":"我不打架。我只是记得你打过。","ps":["守密人不是战士。他们的能力只有一项：记住。别人忘掉的东西，他们替世界记着；替世界记着的东西，他们不能忘，也忘不掉。","弥萨格给每位守密人配一间没有窗的房间，房间里堆满卡片。每一张卡片上写着一个名字、一段残存的记忆、一句那个人最后说过的话。守密人每天要做的事就是重新读一遍——不读，那些东西就会重新滑进融蚀里。","读得久了，卡片会开始回应。你会发现某一张牌的边角是热的，某一张在你手里轻轻动了一下，像有人在里面翻身。那不是错觉：被记住得足够久的东西，会想要回来。"]},{"id":"c3","t":"三 · 唤醒与命轮","sub":"AWAKENING & THE WHEEL","quote":"命轮不是命运。命运不会给你第二次抽牌的机会。","ps":["把一张卡片读到足够熟，卡片上的人就会「醒」。这个过程叫唤醒：不是复活，复活需要尸体；唤醒只需要有人还在想她。醒过来的存在被称为唤醒体，她们有自己的脾气、自己的旧账，以及一个共同的处境——世界已经不记得她们了。","唤醒体不能长期停留在现实里。她们需要一个载体，那就是命轮：一枚刻满刻痕的环。每一道刻痕是一段记忆，每一张卡是一道刻痕的投影。所以牌组不是武器库，是一个人的全部履历。你把谁放进牌组，就等于承认「我记得她」。","命轮也有代价。唤醒体每次被召唤，都要从守密人身上借走一点「确定的记忆」——不是忘掉某件事，而是对某件事不再确定。老练的守密人会把不重要的东西排在前面：今天的天气、昨天的晚饭、自己的生日。"]},{"id":"c4","t":"四 · 四界域","sub":"THE FOUR REALMS","quote":"四个界域，四种还债的方式。","ps":["唤醒体按记忆的质地分成四个界域。这不是地理，是「她属于哪一种遗忘」。","混沌的记忆是烧的，血肉的记忆是疼的，深海的记忆是沉的，超维的记忆是冷的。两个界域的人站在一起，命轮上的刻痕会互相咬合——这就是为什么有些组合一上手就顺，有些怎么打都别扭。","守密人把这种咬合叫做「羁绊」。它不是感情，是结构：两段记忆接得上，力量就会从接缝里漏出来。老守密人带新人时只说一句：先配人，再配牌。"]},{"id":"c5","t":"五 · 决斗链接","sub":"THE DUEL","quote":"输的人不是死。输的人要交出一张牌。","ps":["两个守密人之间的冲突，很少用拳头解决。他们把自己的命轮接上同一台仪器，让两套记忆在中间对撞——这就是「决斗链接」。","对决里的一切都有对应的现实代价：生命值是你还能维持「确定」的总量；祭品是你把两段记忆叠在一起，让位给更强的那个；觉醒召唤是把两个人放进同一张牌，让命轮替她们给出一个答案。答案通常不是她们想要的。","输掉对决的人要交出一张牌：不是丢掉，是「从此不再确定」。那张牌上的人会变淡，下次唤醒她会更难。所以弥萨格的守密人从不轻易开局，也从不轻易认输。","先手不抽牌，是因为先手已经拿到了「先说话」的权利。这条规矩写在弥萨格第一版规程的第一页，据说是被某个守密人用血改上去的。"]},{"id":"c6","t":"六 · 终天教团","sub":"THE ORDER OF THE LAST DAY","quote":"既然都会被忘掉，为什么还要记得？","ps":["终天教团不认为融蚀是灾难，他们认为那是「清洗」。世界之所以痛苦，是因为所有人都在拼命记着不该记的东西；只要全部忘掉，就没有人会被失去弄疼。","教团的守密人也做决斗链接，只是他们的牌组里塞满了「虚无」：不进攻、只拖延、只让对方的每一步都付出代价。他们不追求赢，他们追求让你觉得「记得」这件事很累。","弥萨格官方不承认教团的存在。但档案室里少了一批卡片，少的那批全是「终天」相关的人——这件事没人敢往上报。"]},{"id":"c7","t":"七 · 弥萨格的猫","sub":"THE CAT OF MISAG","quote":"它不属于任何界域。它属于所有界域。","ps":["校猫在弥萨格的地位很奇怪：它不是唤醒体，不在任何一册档案里，也没有人记得它是哪一天出现在走廊上的。它想出现就出现，想消失就消失，四个界域的门对它都是开着的。","有守密人试过把它写进卡片。卡片上确实出现了猫，但那张牌每次打出来的效果都不一样——有时抽牌，有时让对手丢牌，有时什么都没发生，只是猫在牌面上打了一个哈欠。","规程里有一条专门为它加的附注：若对决中出现无法归类的现象，先确认附近有没有猫。"]},{"id":"c8","t":"八 · 卡包的来历","sub":"WHERE THE PACKS COME FROM","quote":"每一包都是一次清点：这些人，我还记得。","ps":["弥萨格的卡片不是印出来的，是「清点」出来的。档案室每隔一段时间要把积压的记忆整理成册，整理完的残页会被压成一套卡包。所以卡包的名字听起来都像档案编号。","「初醒之轮」是最早的一批，混沌与血肉，牌面还是热的；「深潜回响」来自地基下面的四十层，纸是咸的；「超维裂隙」是从裂隙里捞出来的，编号经常对不上；「忘却之诗」全是觉醒体，每一张都写着两个名字。","「校猫的私藏」没有编号，也没有收录记录。它是从校猫睡觉的那个抽屉里掉出来的，一共十四张，其中有一张不是任何人的牌。"]}],"terms":[{"n":"融蚀","d":"一种「撤回」现象。被融蚀的东西不是被毁掉，而是从来没有存在过；连「少了什么」的念头都会一起消失。"},{"n":"弥萨格","d":"最后一座还在「记得」的城市。融蚀在这里推进得最慢，因为有一群人在替世界记着。"},{"n":"守密人","d":"以「记住」为能力的人。玩家在对决中扮演的角色。不战斗，只记得。"},{"n":"唤醒体","d":"被守密人读到「醒」过来的存在。不是复活，是有人还在想她。"},{"n":"命轮","d":"唤醒体的载体，一枚刻满刻痕的环。每一道刻痕是一段记忆，每一张卡是一道刻痕的投影。"},{"n":"界域","d":"按记忆质地划分的四类：混沌（烧）、血肉（疼）、深海（沉）、超维（冷）。"},{"n":"羁绊","d":"两段接得上的记忆。不是感情，是结构；接缝里会漏出力量。"},{"n":"祭品","d":"把两段记忆叠在一起，让位给更强的那个。等级 5–6 需要 1 只，7 以上需要 2 只。"},{"n":"觉醒召唤","d":"把两个人放进同一张牌，从额外卡组召唤觉醒体。素材送墓（至少一只在场上，另一只可从手牌来），不占通常召唤；但刚醒过来的人那一回合还不能动手。"},{"n":"命轮值","d":"本作对「生命值」的叫法。归零不是死，是「不再确定自己是谁」。"},{"n":"银芯","d":"弥萨格的流通物，也是开卡包的代价。打赢人机能拿到一些，难度越高拿得越多——和其他小游戏共用一个钱包。"},{"n":"终天教团","d":"认为忘却才是救赎的教团。牌组以陷阱与拖延为主，不追求赢，只让你觉得「记得」很累。"},{"n":"校猫","d":"不属于任何界域的猫。没有档案，没有编号，四个界域的门对它都开着。"}]};
